"""Tests for scripts/diff_shades_gha_helper.py."""
import json
import os
import unittest
from unittest.mock import patch


class TestConfigCommand(unittest.TestCase):
    """Test the config command output format."""

    @patch.dict(
        os.environ,
        {
            "GITHUB_EVENT_NAME": "push",
            "GITHUB_SHA": "abc123def456",
            "GITHUB_REPOSITORY": "psf/black",
        },
        clear=True,
    )
    @patch("scripts.diff_shades_gha_helper.get_pypi_version")
    def test_config_push_output_format(self, mock_get_pypi_version):
        """Config command for push events produces jobs with 'force-flag' keys."""
        mock_get_pypi_version.return_value = type(
            "Version", (), {"__str__": lambda self: "25.1.0"}
        )()

        from scripts.diff_shades_gha_helper import main

        # Call config with event="push" (parent API)
        try:
            main(["config", "push"], standalone_mode=False)
        except SystemExit:
            pass

